import {
  TypeFace,
  TextInput,
  Box,
  Button,
} from "@greysole/spooder-component-library";
import { useEffect, useState } from "react";
import { useLoginPage } from "./LoginPageContext";

export default function UsernamePasswordForm() {
  const { handleLogin, setRegisterMode } = useLoginPage();
  const [username, setUsername] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  useEffect(() => {
    const handleEnterLogin = (e: KeyboardEvent) => {
      if (e.key === "Enter") {
        handleLogin(username, password);
      }
    };
    document.addEventListener("keydown", handleEnterLogin);
    return () => {
      document.removeEventListener("keydown", handleEnterLogin);
    };
  }, [username, password, handleLogin]);
  return (
    <>
      <TypeFace>Login to this Spooder</TypeFace>
      <TextInput
        value={username}
        onInput={setUsername}
        placeholder="Username"
      />
      <TextInput
        value={password}
        onInput={setPassword}
        placeholder="Password"
        password
      />
      <Box spacing="medium">
        <Button
          label="Register"
          onClick={() => {
            setRegisterMode(true);
          }}
        />
        <Button
          label="Login"
          onClick={() => {
            handleLogin(username, password);
          }}
        />
      </Box>
    </>
  );
}
