import {
  TypeFace,
  TextInput,
  Box,
  Button,
} from "@greysole/spooder-component-library";
import { useState } from "react";
import { useLoginPage } from "./LoginPageContext";

export default function InviteCodeForm() {
  const { handleRegister } = useLoginPage();
  const [inviteCode, setInviteCode] = useState<string>("");
  const [username, setUsername] = useState<string>("");
  const [displayName, setDisplayName] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  const [confirmPassword, setConfirmPassword] = useState<string>("");

  const isValid = username !== "" && password === confirmPassword;
  return (
    <>
      <TypeFace>Enter your invite code</TypeFace>
      <TextInput
        value={inviteCode}
        onInput={setInviteCode}
        placeholder="Enter Invite Code"
      />
      <TextInput
        value={username}
        onInput={setUsername}
        placeholder="New Username"
      />
      <TextInput
        value={displayName}
        onInput={setDisplayName}
        placeholder="New Display Name"
      />
      {password !== "" && confirmPassword !== "" && !isValid ? (
        <TypeFace>Passwords don't match.</TypeFace>
      ) : null}
      <TextInput
        value={password}
        onInput={setPassword}
        placeholder="New Password"
        password
      />
      <TextInput
        value={confirmPassword}
        onInput={setConfirmPassword}
        placeholder="Confirm Password"
        password
      />
      <Box spacing="medium">
        <Button
          label="Register"
          onClick={() => {
            handleRegister(inviteCode, username, displayName, password);
          }}
          disabled={!isValid}
        />
      </Box>
    </>
  );
}
