import React, { createContext, useContext, useState, ReactNode } from "react";
import { login, register } from "../Request";
import {
  Box,
  Border,
  Stack,
  CustomSpooder,
  TypeFace,
} from "@greysole/spooder-component-library";
import UsernamePasswordForm from "./UsernamePasswordForm";
import InviteCodeForm from "./InviteCodeForm";

// Define the context type
interface LoginPageContextType {
  reason: string;
  registerMode: boolean;
  setRegisterMode: (mode: boolean) => void;
  setReason: (reason: string) => void;
  handleLogin: (username: string, password: string) => void;
  handleRegister: (
    inviteCode: string,
    username: string,
    display_name: string,
    password: string
  ) => void;
}

// Create the context with default values
const LoginPageContext = createContext<LoginPageContextType | undefined>(
  undefined
);

export const LoginPageProvider = () => {
  const urlReason = new URLSearchParams(window.location.search).get("reason");
  const [reason, setReason] = useState<string>(urlReason ?? "");
  const [registerMode, setRegisterMode] = useState<boolean>(false);

  const nextUrl = new URLSearchParams(window.location.search).get("next");

  const handleLogin = (username: string, password: string) => {
    login(username, password)
      .then((data) => {
        if (data.status === "active") {
          window.location.href = nextUrl ?? "/mod";
        } else if (data.status === "nolocal") {
          setReason("Lol, you are not a local user");
        } else if (data.status === "temporary") {
          setReason(
            "That's a temporary password. Put in a new one and I'll log you in."
          );
        } else if (data.status === "badpassword") {
          setReason("Wrong password. Try again.");
        }
      })
      .catch((e) => {
        console.error("ERROR", e);
      });
  };

  const handleRegister = (
    inviteCode: string,
    username: string,
    display_name: string,
    password: string
  ) => {
    register(inviteCode, username, display_name, password)
      .then((data) => {
        if (data.status === "verified") {
          setReason("Registration successful! You may login normally.");
          setRegisterMode(false);
        } else {
          setReason(data.message);
        }
      })
      .catch((e) => {
        console.error("ERROR", e);
      });
  };

  const value: LoginPageContextType = {
    reason,
    registerMode,
    setRegisterMode,
    setReason,
    handleLogin,
    handleRegister,
  };

  return (
    <LoginPageContext.Provider value={value}>
      <Box className="login-box">
        <Border>
          <Stack spacing="medium" align="center" padding="medium">
            <CustomSpooder />
            {reason ? <TypeFace>{reason}</TypeFace> : null}
            {registerMode ? <InviteCodeForm /> : <UsernamePasswordForm />}
          </Stack>
        </Border>
      </Box>
    </LoginPageContext.Provider>
  );
};

// Custom hook to use the context
export const useLoginPage = (): LoginPageContextType => {
  const context = useContext(LoginPageContext);
  if (!context) {
    throw new Error("useLoginPage must be used within a LoginPageProvider");
  }
  return context;
};

export default LoginPageContext;
